//! Selected from Ablaut 0.11.0 (MIT), generated by tools/reader-models.
use crate::{conjugate, Conjugation, Lang};
use crate::{lexicon_lemmas, ord};
use std::collections::HashMap;
use std::sync::OnceLock;

/// One analysis of a queried form: an infinitive whose paradigm
/// contains the form, plus every slot the form occupies in it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct ReverseMatch {
    pub(super) infinitive: String,
    /// Slot descriptors like "present 1sg" or "past participle".
    slots: Vec<String>,
}

/// Look up a conjugated form: every infinitive whose paradigm contains
/// it, with the slots it fills. Input is trimmed and case-folded like
/// `from_infinitive`. Ambiguous forms return several matches (French
/// *suis* → être and suivre); unknown forms return an empty vector.
#[must_use]
pub(super) fn reverse(form: &str, lang: Lang) -> Vec<ReverseMatch> {
    let query = form.trim().to_lowercase();
    if query.is_empty() || query.contains(char::is_whitespace) {
        return Vec::new();
    }

    let mut out: Vec<ReverseMatch> = Vec::new();
    if let Some(hits) = index(lang).get(&query) {
        let mut by_lemma: Vec<(String, Vec<String>)> = Vec::new();
        for (inf, slot) in hits {
            if lang == Lang::Fra && FRA_BOUND_STEMS.contains(&inf.as_str()) {
                continue;
            }
            match by_lemma.iter_mut().find(|(l, _)| l == inf) {
                Some((_, slots)) => {
                    if !slots.contains(slot) {
                        slots.push(slot.clone());
                    }
                }
                None => by_lemma.push((inf.clone(), vec![slot.clone()])),
            }
        }
        by_lemma.sort_by(|a, b| a.0.cmp(&b.0));
        out.extend(
            by_lemma
                .into_iter()
                .map(|(infinitive, slots)| ReverseMatch { infinitive, slots }),
        );
    }
    let indexed_hit = !out.is_empty();

    let mut cands = candidates(&query, lang);
    let spellings = if lang == Lang::Deu {
        deu_spellings(&query)
    } else {
        vec![query.clone()]
    };
    for q in &spellings {
        if q != &query {
            if let Some(hits) = index(lang).get(q.as_str()) {
                for (inf, _) in hits {
                    if !cands.contains(inf) {
                        cands.push(inf.clone());
                    }
                }
            }
        }
        for (i, _) in q.char_indices().skip(1) {
            let mut push_hits = |key: &str| {
                if let Some(hits) = index(lang).get(key) {
                    for (inf, _) in hits {
                        let cand = format!("{}{inf}", &q[..i]);
                        if !cands.contains(&cand) {
                            cands.push(cand);
                        }
                    }
                }
            };
            push_hits(&q[i..]);
            if lang == Lang::Deu {
                push_hits(&format!("ge{}", &q[i..]));
            }
        }
    }

    let mut verified: Vec<ReverseMatch> = Vec::new();
    for cand in cands {
        if out.iter().any(|m| m.infinitive == cand) {
            continue;
        }
        if indexed_hit && is_index_shadow(&cand, &query, lang) {
            continue;
        }
        if let Some(m) = verify(&cand, &query, lang) {
            if !verified.iter().any(|v| v.infinitive == m.infinitive) {
                verified.push(m);
            }
        }
    }
    if lang == Lang::Eng && indexed_hit {
        verified.retain(|m| m.infinitive != query || m.slots.iter().any(|s| s != "infinitive"));
    }

    let keep: Vec<bool> = verified
        .iter()
        .map(|m| {
            !canonical_twins(&m.infinitive, lang).iter().any(|t| {
                t != &m.infinitive
                    && (verified.iter().any(|v| &v.infinitive == t)
                        || out.iter().any(|v| &v.infinitive == t))
            })
        })
        .collect();
    let mut verified: Vec<ReverseMatch> = verified
        .into_iter()
        .zip(keep)
        .filter_map(|(m, k)| k.then_some(m))
        .collect();

    verified.sort_by(|a, b| {
        a.infinitive
            .chars()
            .count()
            .cmp(&b.infinitive.chars().count())
            .then_with(|| a.infinitive.cmp(&b.infinitive))
    });
    out.extend(verified);
    out
}

/// The productive ghost shapes that shadow every irregular form and
/// are only worth suppressing when the index already explains the
/// query: the French second-group reading (any X-is/X-it form yields
/// a hypothetical X-ir) and the German weak verb built on the query
/// itself as a stem (war → *waren). Lexicon lemmas are never ghosts.
fn is_index_shadow(cand: &str, query: &str, lang: Lang) -> bool {
    if is_lexicon_lemma(cand, lang) {
        return false;
    }
    match lang {
        Lang::Fra => cand.ends_with("ir") || cand.ends_with("re"),
        Lang::Deu => cand
            .strip_suffix('n')
            .is_some_and(|b| b == query || b.strip_suffix('e') == Some(query)),
        _ => false,
    }
}

/// Forward-conjugate `cand` and collect the slots where `query`
/// appears. None when the candidate is not a verb shape the engine
/// accepts, or its paradigm does not contain the query.
fn verify(cand: &str, query: &str, lang: Lang) -> Option<ReverseMatch> {
    let mut slots: Vec<String> = Vec::new();
    let mut infinitive = None;
    for (form, slot) in forms_for(cand, lang)? {
        if slot == "infinitive" {
            infinitive = Some(form.clone());
        }
        let form = form.to_lowercase();
        let hit = form == query
            || (lang == Lang::Deu && deu_variant_match(&form, query))
            || (lang == Lang::Eng && eng_variant_match(&form, query));
        if hit && !slots.contains(&slot) {
            slots.push(slot);
        }
    }
    let infinitive = infinitive?;
    (!slots.is_empty()).then_some(ReverseMatch { infinitive, slots })
}

/// German spelling variants the engine does not emit but the written
/// language allows: the optional imperative/1sg schwa (meid/meide,
/// dulde/duld), the epenthetic -e- of 2sg/2pl endings (überträfst/
/// überträfest), and the mobile schwa of -eln/-ern stems (heuchle/
/// heuchele, verringert/verringret). A table form matches a query if
/// one rewrite bridges them.
fn deu_variant_match(form: &str, query: &str) -> bool {
    if let Some(b) = form.strip_suffix('e') {
        if b == query {
            return true;
        }
    }
    if query.strip_suffix('e') == Some(form) {
        return true;
    }
    for (a, b) in DEU_REWRITES {
        if let Some(stem) = form.strip_suffix(a) {
            if query.strip_prefix(stem) == Some(b) {
                return true;
            }
        }
    }
    false
}

/// The British doubled-l spelling (travelling, mislabelled) matched
/// against the engine's single-l American forms. Restricted to -ll-
/// after a longer stem so filled does not match file's *filed.
fn eng_variant_match(form: &str, query: &str) -> bool {
    for suf in ["ing", "ed"] {
        if let Some(qstem) = query.strip_suffix(suf) {
            if qstem.ends_with("ll") && qstem.len() >= 6 {
                if let Some(d) = degeminate(qstem) {
                    if format!("{d}{suf}") == form {
                        return true;
                    }
                }
            }
        }
    }
    false
}

/// The spellings a German query might be written in besides its own:
/// the same rewrites, applied to the query. Used to anchor prefixed
/// recombination (vorzögst → vorzögest, whose -zögest tail the index
/// knows as ziehen).
fn deu_spellings(query: &str) -> Vec<String> {
    let mut v = vec![query.to_string()];
    match query.strip_suffix('e') {
        Some(b) => v.push(b.to_string()),
        None => v.push(format!("{query}e")),
    }
    for (a, b) in DEU_REWRITES {
        if let Some(stem) = query.strip_suffix(a) {
            v.push(format!("{stem}{b}"));
        }
    }
    v
}

const DEU_REWRITES: [(&str, &str); 30] = [
    ("est", "st"),
    ("st", "est"),
    ("et", "t"),
    ("t", "et"),
    ("tet", "etet"),
    ("etet", "tet"),
    ("te", "ete"),
    ("ete", "te"),
    ("ten", "eten"),
    ("eten", "ten"),
    ("test", "etest"),
    ("etest", "test"),
    ("elst", "lest"),
    ("lest", "elst"),
    ("ert", "ret"),
    ("ret", "ert"),
    ("elt", "let"),
    ("let", "elt"),
    ("le", "ele"),
    ("ele", "le"),
    ("re", "ere"),
    ("ere", "re"),
    ("re", "er"),
    ("er", "re"),
    ("le", "el"),
    ("el", "le"),
    ("eln", "len"),
    ("ern", "ren"),
    ("erst", "rest"),
    ("rest", "erst"),
];

/// Every single-word form of a lemma with its slot descriptor. For
/// most languages this is the `Table`; French and Spanish also emit
/// spelling variants (payer's *paye*, the Spanish -se subjunctive,
/// and the 1990 French grave-accent future).
fn forms_for(lemma: &str, lang: Lang) -> Option<Vec<(String, String)>> {
    match lang {
        Lang::Fra => fra_forms(lemma),
        Lang::Spa => spa_forms(lemma),
        Lang::Deu => deu_forms(lemma),
        Lang::Eng => conjugate(lemma, lang).map(|t| enumerate(&t)),
    }
}

/// German forms, with the clause-final spelling of separable verbs
/// joined back on: the table renders "dankten ab", but in subordinate
/// clauses the same slot is written *abdankten*, and that is the form
/// corpora index. Two-word forms whose second word is the verb's own
/// leading particle are re-joined; live recombination of free-standing
/// "fängt ... an" word pairs stays out of scope.
fn deu_forms(lemma: &str) -> Option<Vec<(String, String)>> {
    let table = conjugate(lemma, Lang::Deu)?;
    let Conjugation::Deu(t) = &table else {
        unreachable!()
    };
    let infinitive = t.infinitive.clone();
    let mut forms = enumerate(&table);
    let mut joined: Vec<(String, String)> = Vec::new();
    let mut join = |row: &[String], tense: &str, labels: &[&str]| {
        for (f, l) in row.iter().zip(labels) {
            if let Some((verb, particle)) = f.split_once(' ') {
                if !particle.contains(' ') && infinitive.starts_with(particle) {
                    joined.push((
                        format!("{particle}{verb}"),
                        format!("{tense} {l} (clause-final)"),
                    ));
                }
            }
        }
    };
    join(&t.present, "present", &P6);
    join(&t.preterite, "preterite", &P6);
    join(&t.konjunktiv1, "konjunktiv i", &P6);
    join(&t.konjunktiv2, "konjunktiv ii", &P6);
    forms.append(&mut joined);
    Some(forms)
}

fn fra_forms(lemma: &str) -> Option<Vec<(String, String)>> {
    use ablaut::fra::{Number, Person, SimpleTense, Verb};
    let v = Verb::from_infinitive(lemma).ok()?;
    let mut s = Slots(Vec::new());
    s.one(&v.infinitive(), "infinitive");
    for f in v.present_participle_variants() {
        s.one(&f, "present participle");
    }
    let pp = v.past_participle();
    s.one(&pp, "past participle");
    if !pp.ends_with('s') && !pp.ends_with('x') {
        s.one(&format!("{pp}s"), "past participle masc pl");
    }
    s.one(&format!("{pp}e"), "past participle fem sg");
    s.one(&format!("{pp}es"), "past participle fem pl");
    let persons = [
        (Person::First, Number::Singular, "1sg"),
        (Person::Second, Number::Singular, "2sg"),
        (Person::Third, Number::Singular, "3sg"),
        (Person::First, Number::Plural, "1pl"),
        (Person::Second, Number::Plural, "2pl"),
        (Person::Third, Number::Plural, "3pl"),
    ];
    for (p, n, l) in [
        (Person::Second, Number::Singular, "2sg"),
        (Person::First, Number::Plural, "1pl"),
        (Person::Second, Number::Plural, "2pl"),
    ] {
        for f in v.imperative_variants(p, n) {
            s.one(&f, &format!("imperative {l}"));
        }
    }
    for (t, name) in [
        (SimpleTense::Present, "present"),
        (SimpleTense::Imperfect, "imperfect"),
        (SimpleTense::PastHistoric, "past historic"),
        (SimpleTense::Future, "future"),
        (SimpleTense::Conditional, "conditional"),
        (SimpleTense::SubjunctivePresent, "subjunctive present"),
        (SimpleTense::SubjunctiveImperfect, "subjunctive imperfect"),
    ] {
        for (p, n, l) in persons {
            for f in v.variants(t, p, n) {
                s.one(&f, &format!("{name} {l}"));
            }
        }
    }
    Some(s.0)
}

fn spa_forms(lemma: &str) -> Option<Vec<(String, String)>> {
    use ablaut::spa::{Number, Person, SimpleTense, Verb};
    let v = Verb::from_infinitive(lemma).ok()?;
    let mut s = Slots(Vec::new());
    s.one(&v.infinitive(), "infinitive");
    s.one(&v.gerund(), "gerund");
    for (fem, pl, l) in [
        (false, false, "masc sg"),
        (true, false, "fem sg"),
        (false, true, "masc pl"),
        (true, true, "fem pl"),
    ] {
        s.one(
            &v.past_participle_inflected(fem, pl),
            &format!("past participle {l}"),
        );
    }
    let persons = [
        (Person::First, Number::Singular, "1sg"),
        (Person::Second, Number::Singular, "2sg"),
        (Person::Third, Number::Singular, "3sg"),
        (Person::First, Number::Plural, "1pl"),
        (Person::Second, Number::Plural, "2pl"),
        (Person::Third, Number::Plural, "3pl"),
    ];
    for (p, n, l) in [
        (Person::Second, Number::Singular, "tú"),
        (Person::Third, Number::Singular, "usted"),
        (Person::First, Number::Plural, "nosotros"),
        (Person::Second, Number::Plural, "vosotros"),
        (Person::Third, Number::Plural, "ustedes"),
    ] {
        if let Some(f) = v.imperative(p, n) {
            s.one(&f, &format!("imperative {l}"));
        }
    }
    for (t, name) in [
        (SimpleTense::Present, "present"),
        (SimpleTense::Imperfect, "imperfect"),
        (SimpleTense::Preterite, "preterite"),
        (SimpleTense::Future, "future"),
        (SimpleTense::Conditional, "conditional"),
        (SimpleTense::SubjunctivePresent, "subjunctive present"),
        (SimpleTense::SubjunctiveImperfect, "subjunctive imperfect"),
        (SimpleTense::SubjunctiveFuture, "subjunctive future"),
    ] {
        for (p, n, l) in persons {
            for f in v.variants(t, p, n) {
                s.one(&f, &format!("{name} {l}"));
            }
        }
    }
    Some(s.0)
}

const FR_VOWELS: &str = "aeiouyàâéèêëîïôûü";

/// Candidate infinitives for the productive de-inflection path.
/// Over-generation is fine — every candidate is verified by forward
/// conjugation — so the generators favour recall over precision.
fn candidates(query: &str, lang: Lang) -> Vec<String> {
    let mut set: Vec<String> = Vec::new();
    let mut push = |s: String| {
        if !set.contains(&s) {
            set.push(s);
        }
    };
    let prefixes = |s: &str| -> Vec<String> {
        s.char_indices()
            .skip(1)
            .map(|(i, _)| s[..i].to_string())
            .chain(std::iter::once(s.to_string()))
            .collect()
    };
    match lang {
        Lang::Fra => {
            let mut stems = prefixes(query);
            for stem in prefixes(query) {
                if let Some(d) = degeminate(&stem) {
                    stems.push(d);
                }
                if let Some(i) = stem.rfind('è') {
                    stems.push(format!("{}é{}", &stem[..i], &stem[i + "è".len()..]));
                    stems.push(format!("{}e{}", &stem[..i], &stem[i + "è".len()..]));
                }
                if let Some(base) = stem.strip_suffix('i') {
                    if base.chars().last().is_some_and(|c| FR_VOWELS.contains(c)) {
                        stems.push(format!("{base}y"));
                    }
                }
                if let Some(base) = stem.strip_suffix('ç') {
                    stems.push(format!("{base}c"));
                }
            }
            for stem in stems {
                for end in ["er", "ir", "re"] {
                    push(format!("{stem}{end}"));
                }
            }
        }
        Lang::Spa => {
            let mut stems = prefixes(query);
            for stem in prefixes(query) {
                for (from, tos) in [("ue", &["o", "u"][..]), ("ie", &["e", "i"]), ("i", &["e"])] {
                    if let Some(i) = stem.rfind(from) {
                        for to in tos {
                            stems.push(format!("{}{to}{}", &stem[..i], &stem[i + from.len()..]));
                        }
                    }
                }
                for (suf, to) in [
                    ("qu", "c"),
                    ("gu", "g"),
                    ("c", "z"),
                    ("j", "g"),
                    ("gü", "gu"),
                    ("zc", "c"),
                    ("uy", "ü"),
                ] {
                    if let Some(base) = stem.strip_suffix(suf) {
                        stems.push(format!("{base}{to}"));
                    }
                }
            }
            for stem in stems {
                for end in ["ar", "er", "ir"] {
                    push(format!("{stem}{end}"));
                }
            }
            let bare = query.strip_suffix('s').unwrap_or(query);
            let bare = match bare.strip_suffix('a') {
                Some(b) => format!("{b}o"),
                None => bare.to_string(),
            };
            for (pat, repl) in [("ierto", "rir"), ("crito", "cribir"), ("uelto", "olver")] {
                if let Some(base) = bare.strip_suffix(pat) {
                    push(format!("{base}{repl}"));
                }
            }
        }
        Lang::Deu => {
            let mut bases = vec![query.to_string()];
            for infix in ["ge", "zu"] {
                let mut at = 0;
                while let Some(i) = query[at..].find(infix) {
                    let i = at + i;
                    bases.push(format!("{}{}", &query[..i], &query[i + infix.len()..]));
                    at = i + infix.len();
                }
            }
            for base in bases {
                let mut stems = prefixes(&base);
                for stem in prefixes(&base) {
                    for (from, to) in [("äu", "au"), ("ä", "a"), ("ö", "o"), ("ü", "u")] {
                        if let Some(i) = stem.rfind(from) {
                            stems.push(format!("{}{to}{}", &stem[..i], &stem[i + from.len()..]));
                        }
                    }
                    if stem.ends_with(['l', 'r']) && stem.chars().count() >= 3 {
                        let cut = stem.len() - 1;
                        stems.push(format!("{}e{}", &stem[..cut], &stem[cut..]));
                    }
                }
                for stem in stems {
                    push(format!("{stem}en"));
                    push(format!("{stem}n"));
                }
            }
        }
        Lang::Eng => {
            let mut stems = prefixes(query);
            for stem in prefixes(query) {
                if let Some(d) = degeminate(&stem) {
                    stems.push(d);
                }
                if let Some(base) = stem.strip_suffix('i') {
                    stems.push(format!("{base}y"));
                }
            }
            for stem in stems {
                push(stem.clone());
                push(format!("{stem}e"));
            }
        }
    }
    set
}

/// Undouble a stem-final geminate consonant (appell → appel).
fn degeminate(stem: &str) -> Option<String> {
    let mut chars = stem.chars();
    let last = chars.next_back()?;
    let prev = chars.next_back()?;
    (last == prev && last.is_alphabetic() && !"aeiouyàâéèêëîïôûü".contains(last))
        .then(|| stem[..stem.len() - last.len_utf8()].to_string())
}

/// More canonical spellings of a candidate infinitive: if one of these
/// is itself a verified match, the candidate is an orthographic ghost
/// of it (appeller of appeler, cèder of céder, stoppe of stop) and is
/// dropped. Deliberately narrow — real doublets stay untouched.
/// Only French has twins worth filtering. There is deliberately no
/// degemination twin (for "appellerons" both appeler and an -eller
/// reading genuinely exist in French orthography), and English is left
/// unfiltered: for "advised" both advise and the nonce *advis verify,
/// and no orthographic rule can pick one without claiming the other
/// direction for "stopped" (stop vs *stoppe).
fn canonical_twins(cand: &str, lang: Lang) -> Vec<String> {
    let mut twins = Vec::new();
    if lang == Lang::Fra {
        for end in ["er", "ir", "re"] {
            if let Some(stem) = cand.strip_suffix(end) {
                if let Some(base) = stem.strip_suffix('i') {
                    if base.chars().last().is_some_and(|c| FR_VOWELS.contains(c)) {
                        twins.push(format!("{base}y{end}"));
                    }
                }
            }
        }
        if let Some(i) = cand.rfind('è') {
            twins.push(format!("{}é{}", &cand[..i], &cand[i + "è".len()..]));
            twins.push(format!("{}e{}", &cand[..i], &cand[i + "è".len()..]));
        }
    }
    twins
}

type Index = HashMap<String, Vec<(String, String)>>;

fn index(lang: Lang) -> &'static Index {
    #[allow(clippy::declare_interior_mutable_const)]
    const EMPTY: OnceLock<Index> = OnceLock::new();
    static INDEXES: [OnceLock<Index>; 4] = [EMPTY; 4];
    INDEXES[ord(lang)].get_or_init(|| build_index(lang))
}

fn build_index(lang: Lang) -> Index {
    let mut idx: Index = HashMap::new();
    for lemma in lexicon_lemmas(lang) {
        let Some(forms) = forms_for(lemma, lang) else {
            continue;
        };
        let mut infinitive = lemma.to_string();
        for (form, slot) in &forms {
            if slot == "infinitive" {
                infinitive.clone_from(form);
            }
        }
        for (form, slot) in forms {
            let entry = idx.entry(form.to_lowercase()).or_default();
            let pair = (infinitive.clone(), slot);
            if !entry.contains(&pair) {
                entry.push(pair);
            }
        }
    }
    idx
}

fn is_lexicon_lemma(cand: &str, lang: Lang) -> bool {
    #[allow(clippy::declare_interior_mutable_const)]
    const EMPTY: OnceLock<std::collections::HashSet<&'static str>> = OnceLock::new();
    static SETS: [OnceLock<std::collections::HashSet<&'static str>>; 4] = [EMPTY; 4];
    SETS[ord(lang)]
        .get_or_init(|| lexicon_lemmas(lang).into_iter().collect())
        .contains(cand)
}

/// French lexicon rows that are bound stems, not verbs (conduire's
/// -uire, écrire's -crire): excluded from the index so they never
/// surface as infinitives.
const FRA_BOUND_STEMS: [&str; 7] = [
    "crire", "uire", "clure", "cevoir", "eindre", "oindre", "aindre",
];

const P6: [&str; 6] = ["1sg", "2sg", "3sg", "1pl", "2pl", "3pl"];
struct Slots(Vec<(String, String)>);

impl Slots {
    fn one(&mut self, form: &str, name: &str) {
        if !form.is_empty()
            && form != "-"
            && form != "\u{2014}"
            && !form.contains(char::is_whitespace)
        {
            self.0.push((form.to_string(), name.to_string()));
        }
    }
    fn opt(&mut self, form: Option<&String>, name: &str) {
        if let Some(f) = form {
            self.one(f, name);
        }
    }
    fn row(&mut self, forms: &[String], tense: &str, labels: &[&str]) {
        for (f, l) in forms.iter().zip(labels) {
            self.one(f, &format!("{tense} {l}"));
        }
    }
    fn row_opt(&mut self, forms: &[Option<String>], tense: &str, labels: &[&str]) {
        for (f, l) in forms.iter().zip(labels) {
            self.opt(f.as_ref(), &format!("{tense} {l}"));
        }
    }
}

/// Enumerate the synthetic, single-word forms of a table with slot
/// descriptors. Analytic tenses and auxiliary listings are skipped: an
/// auxiliary is not a form of the verb, and analytic forms are
/// multi-word. The infinitive slot is always named "infinitive".
#[allow(clippy::too_many_lines)]
fn enumerate(c: &Conjugation) -> Vec<(String, String)> {
    let mut s = Slots(Vec::new());
    match c {
        Conjugation::Deu(t) => {
            s.one(&t.infinitive, "infinitive");
            s.one(&t.zu_infinitive, "zu-infinitive");
            s.one(&t.present_participle, "present participle");
            s.one(&t.past_participle, "past participle");
            s.row_opt(&t.imperative, "imperative", &["2sg", "2pl"]);
            s.row(&t.present, "present", &P6);
            s.row(&t.preterite, "preterite", &P6);
            s.row(&t.konjunktiv1, "konjunktiv i", &P6);
            s.row(&t.konjunktiv2, "konjunktiv ii", &P6);
        }
        Conjugation::Eng(t) => {
            s.one(&t.infinitive, "infinitive");
            s.one(&t.past, "past");
            s.one(&t.past_participle, "past participle");
            s.one(&t.present_participle, "present participle");
            s.one(&t.third_singular, "present 3sg");
        }
    }
    s.0
}
